/* From Uiverse.io by Cobp  - Tags: material design, animation, card, modern */
.__UIV_SCOPE__ .card {
  position: relative;
  display: flex;
  width: 350px;
  background-color: #242824;
  padding: 10px;
  border-radius: 6px;
  gap: 0.5rem;
  height: max-content;
}
.__UIV_SCOPE__ .bar {
  width: 10px;
  border-radius: 5px;
  background-color: #9147ff;
  transition: all 0.5s ease-in-out;
}
.__UIV_SCOPE__ .card:hover .bar {
  margin-right: 5px;
}
.__UIV_SCOPE__ .card_form {
  position: relative;
  min-width: 5em;
  min-height: 5em;
  border-radius: 4px;
  background-color: #9147ff;
  transition: 0.2s ease-in-out;
  overflow: hidden;
}
.__UIV_SCOPE__ .card_data {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.__UIV_SCOPE__ .card_data span {
  color: #9147ff;
  margin-top: auto;
  font-size: 0.9em;
  transition: 0.2s ease-in-out;
  cursor: pointer;
}
.__UIV_SCOPE__ .card_data span:hover {
  color: #28aea5;
  text-decoration: underline;
}
.__UIV_SCOPE__ .text {
  display: flex;
  justify-content: center;
  flex-direction: column;
  margin-left: 0.5em;
  color: white;
}
.__UIV_SCOPE__ .text_m {
  font-size: 0.9em;
}
.__UIV_SCOPE__ .text_s {
  color: #9147ff;
  font-size: 0.6em;
}
.__UIV_SCOPE__ .text_d {
  font-size: 0.7em;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
}
.__UIV_SCOPE__ .cube {
  width: max-content;
  height: 10px;
  transition: all 0.2s;
  transform-style: preserve-3d;
}
.__UIV_SCOPE__ .card:hover .cube {
  transform: rotateX(90deg);
}
.__UIV_SCOPE__ .side {
  width: max-content;
  height: 1em;
  display: flex;
  justify-content: center;
  align-items: center;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: bold;
}
.__UIV_SCOPE__ .top {
  transform: rotateX(-90deg) translate3d(0, 0, 0em);
}
.__UIV_SCOPE__ .front {
  transform: translate3d(0, 0, 1em);
}
